#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/rtio/rtio.h>
#include <string.h>

#define RTIO_TEST_SQ_COUNT 4
#define RTIO_TEST_CQ_COUNT 4
#define RTIO_TEST_BUF_SIZE 64

static struct rtio_sqe sq_pool[RTIO_TEST_SQ_COUNT];
static struct rtio_cqe cq_pool[RTIO_TEST_CQ_COUNT];
static uint8_t rtio_buffer[RTIO_TEST_BUF_SIZE];

RTIO_DEFINE_WITH_MEMPOOL(test_rtio_ctx, RTIO_TEST_SQ_COUNT, RTIO_TEST_CQ_COUNT,
                         sq_pool, cq_pool, rtio_buffer, sizeof(rtio_buffer));

static void *rtio_api_setup(void)
{
    // Re-initialize the RTIO context for each test to ensure a clean state
    rtio_init(&test_rtio_ctx);
    return NULL;
}

static void rtio_api_teardown(void *fixture)
{
    // No specific teardown needed for this simple context
}

ZTEST_SUITE(rtio_api_tests, NULL, rtio_api_setup, NULL, rtio_api_teardown, NULL);

ZTEST(rtio_api_tests, test_rtio_sqe_copy_in_full)
{
    struct rtio_sqe *sqe;
    int i;

    // Fill the submission queue to capacity by acquiring all available SQEs
    for (i = 0; i < RTIO_TEST_SQ_COUNT; i++) {
        sqe = rtio_sqe_acquire(&test_rtio_ctx);
        zassert_not_null(sqe, "Failed to acquire SQE %d when queue should not be full", i);
        // Do not submit them yet, just acquire to occupy the slots.
        // In a real scenario, these would be submitted and processed.
    }

    // Attempt to acquire one more SQE, expecting it to fail (return NULL)
    sqe = rtio_sqe_acquire(&test_rtio_ctx);

    // The fix: Assert that sqe IS NULL, because the queue should now be full.
    // The original code likely proceeded to use 'sqe' here without checking,
    // leading to the assertion failure in rtio.h when 'sqe' was NULL.
    zassert_is_null(sqe, "Acquired SQE when queue should be full");

    // If the test was meant to test rtio_sqe_copy_in with a full *buffer* (not queue),
    // the logic would be different. But the assertion 'sqe != ((void *)0)'
    // points to the sqe pointer itself being NULL, which happens when acquisition fails.
    // The test name 'copy_in_full' strongly suggests testing the queue full condition.
}
